import{At as e,Q as t,St as n,at as r,it as i,nt as a,ot as o,st as s,t as c,vt as l}from"./chunks/framework.B8IeflXD.js";var u=JSON.parse(`{"title":"Head to head with MUI X Data Grid","description":"","frontmatter":{},"headers":[],"relativePath":"versus.md","filePath":"pages/2_versus.md"}`),d={name:`versus.md`};function f(c,u,d,f,p,m){let h=n(`Mermaid`);return l(),i(`div`,null,[u[1]||=r(`<h1 id="head-to-head-with-mui-x-data-grid" tabindex="-1">Head to head with MUI X Data Grid <a class="header-anchor" href="#head-to-head-with-mui-x-data-grid" aria-label="Permalink to “Head to head with MUI X Data Grid”">​</a></h1><p>Measured. Both grids are mounted over the same rows, the same five columns at the same pixel widths, the same 36 px row height and the same cell content, then scrolled by the same harness in the same chromium, and read through the same CDP counters.</p><p><code>docs/1_parity.md</code> answers which features each one has. This answers what a scroll costs, including the two columns where MUI X is faster.</p><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><ol><li><a href="#_1-what-was-run">What was run</a></li><li><a href="#_2-the-structural-result-the-mit-tier-stops-at-100-rows">The structural result: the MIT tier stops at 100 rows</a></li><li><a href="#_3-the-matrix">The matrix</a></li><li><a href="#_4-where-mui-x-wins">Where MUI X wins</a></li><li><a href="#_5-where-signal-grid-wins">Where signal-grid wins</a></li><li><a href="#_6-row-count-ceiling">Row-count ceiling</a></li><li><a href="#_7-what-a-reactslot-cell-costs">What a <code>reactSlot</code> cell costs</a></li><li><a href="#_8-what-this-does-not-measure">What this does not measure</a></li><li><a href="#_9-reproducing-it">Reproducing it</a></li></ol><h2 id="_1-what-was-run" tabindex="-1">1. What was run <a class="header-anchor" href="#_1-what-was-run" aria-label="Permalink to “1. What was run”">​</a></h2>`,6),(l(),a(t,null,{default:e(()=>[s(h,{id:`mermaid-62`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20H%5B%22bench%2Fscroll%2F1_run.ts%3Cbr%2F%3Eburst(warm%2C%20frames)%22%5D%20--%3E%20A%5B%22index.html%3Cbr%2F%3Esignal-grid%2C%20DOM%20slot%22%5D%0A%20%20H%20--%3E%20B%5B%22react.html%3Cbr%2F%3Esignal-grid%2C%20reactSlot%22%5D%0A%20%20H%20--%3E%20C%5B%22mui.html%3Cbr%2F%3E%26lt%3BDataGrid%20%2F%26gt%3B%209.13.0%22%5D%0A%20%20A%20--%3E%20W%5B%22window.__bench%22%5D%0A%20%20B%20--%3E%20W%0A%20%20C%20--%3E%20W%0A%20%20W%20--%3E%20R%5B%22bench%2Fversus.mjs%3Cbr%2F%3Eone%20chromium%2C%20one%20flag%20set%22%5D%0A%20%20R%20--%3E%20M%5B%22CDP%20Performance.getMetrics%3Cbr%2F%3Eeither%20side%20of%20the%20burst%22%5D%0A%20%20R%20--%3E%20J%5B%22bench%2Fversus.json%3Cbr%2F%3Ebench%2Fversus.svg%22%5D%0A`})]),fallback:e(()=>[...u[0]||=[o(` Loading... `,-1)]]),_:1})),u[2]||=r(`<p>Every page exports the same <code>window.__bench(warm, frames)</code> and the same <code>window.__firstRow</code>, both built in <code>bench/scroll/1_run.ts</code>, so the runner never branches on which engine it is driving.</p><table tabindex="0"><thead><tr><th>held equal</th><th>value</th></tr></thead><tbody><tr><td>rows</td><td>one materialised array per cell, identical generator (<code>rowAt</code> in <code>bench/scroll/0_bench.ts</code>)</td></tr><tr><td>columns</td><td>Name 220, Size 120, Share 160, Trend 100, Index 100</td></tr><tr><td>heavy cell</td><td>the same 9-element stack, including a 16-<code>rect</code> sparkline, from <code>bench/scroll/2_heavy.tsx</code></td></tr><tr><td>row height</td><td>36 px, declared, both sides</td></tr><tr><td>warmup</td><td>40 frames as their own burst, discarded, so the CDP deltas cover only measured frames</td></tr><tr><td>measured</td><td>120 frames at 240 px each, reversing at either end of the scroller</td></tr><tr><td>browser</td><td>one headless chromium, <code>--enable-precise-memory-info</code>, through <code>scripts/browser-queue.mjs</code></td></tr><tr><td>heap</td><td><code>HeapProfiler.collectGarbage</code> before every read</td></tr></tbody></table><p>Varied: relation size (101, 1,000, 100,000), cell weight (plain, heavy), viewport box (720x480, 1600x900, 2560x1440), and buffer (overscan 4, overscan 32).</p><p>Two equalisations are worth naming. MUI X&#39;s buffer is <code>rowBufferPx</code> and its floor is <code>averageRowHeight * 15</code>, so it holds a minimum of 15 buffered rows whatever is asked for; the <code>rows held</code> column reports what each engine actually kept. And the scroll reverses at the bottom stop instead of stopping, because MUI X&#39;s scroller runs out of travel after 3,600 px.</p><h2 id="_2-the-structural-result-the-mit-tier-stops-at-100-rows" tabindex="-1">2. The structural result: the MIT tier stops at 100 rows <a class="header-anchor" href="#_2-the-structural-result-the-mit-tier-stops-at-100-rows" aria-label="Permalink to “2. The structural result: the MIT tier stops at 100 rows”">​</a></h2><p><code>&lt;DataGrid /&gt;</code> forces <code>pagination: true</code> in <code>node_modules/@mui/x-data-grid/DataGrid/useDataGridProps.mjs</code>, and <code>pageSize</code> throws above 100 in <code>node_modules/@mui/x-data-grid/hooks/features/pagination/gridPaginationUtils.mjs</code>:</p><blockquote><p>MUI X: <code>pageSize</code> cannot exceed 100 in the MIT version of the DataGrid. You need to upgrade to DataGridPro or DataGridPremium component to unlock this feature.</p></blockquote><p>So the scroller is 3,600 px deep whatever the <code>rows</code> prop carries. Handed 100,000 rows, MUI X renders a 100-row page and a pager; the <code>scroll rows</code> column below reads 101 on every MUI row of the matrix and 100,001 on every signal-grid row of it. Nothing on the page can lift that, and no bench harness can measure a million-row scroll on a grid that will not perform one.</p><p>The rest of the numbers are therefore read two ways. Per frame the comparison is fair, because both engines move 240 px and recycle the same number of rows across the viewport edge. Per relation it is not, and the <code>101 rows</code> case exists for exactly that reason: it gives signal-grid the same scroll depth MUI X is capped at, so the per-frame columns can be read without the relation size in them.</p><h2 id="_3-the-matrix" tabindex="-1">3. The matrix <a class="header-anchor" href="#_3-the-matrix" aria-label="Permalink to “3. The matrix”">​</a></h2><p>Ratios in this page are stated so that a number above 1 means signal-grid is cheaper.</p><table tabindex="0"><thead><tr><th>case</th><th>engine</th><th>p50 ms</th><th>p95 ms</th><th>worst ms</th><th>slow</th><th>rows held</th><th>scroll rows</th><th>nodes</th><th>settled nodes</th><th>layout ms/f</th><th>style ms/f</th><th>script ms/f</th><th>heap MB</th><th>first row ms</th></tr></thead><tbody><tr><td>101 rows, heavy, 1600x900</td><td>signal-grid</td><td>8.3</td><td>9.4</td><td>10.8</td><td>0</td><td>34</td><td>102</td><td>1412</td><td>1914</td><td>0.98</td><td>1.23</td><td>0.94</td><td>3.5</td><td>94.1</td></tr><tr><td>101 rows, heavy, 1600x900</td><td>signal-grid + reactSlot</td><td>8.2</td><td>9.2</td><td>10.0</td><td>0</td><td>34</td><td>102</td><td>1344</td><td>1603</td><td>1.06</td><td>1.32</td><td>2.16</td><td>5.8</td><td>45.4</td></tr><tr><td>101 rows, heavy, 1600x900</td><td>MUI X 9.13.0</td><td>8.3</td><td>9.2</td><td>16.7</td><td>0</td><td>41</td><td>101</td><td>1798</td><td>2186</td><td>0.28</td><td>0.30</td><td>1.99</td><td>9.4</td><td>150.0</td></tr><tr><td>1k rows, heavy, 1600x900</td><td>signal-grid</td><td>8.3</td><td>9.2</td><td>9.4</td><td>0</td><td>34</td><td>1001</td><td>1412</td><td>2072</td><td>1.45</td><td>1.26</td><td>1.07</td><td>3.8</td><td>38.1</td></tr><tr><td>1k rows, heavy, 1600x900</td><td>signal-grid + reactSlot</td><td>8.3</td><td>9.4</td><td>11.2</td><td>0</td><td>34</td><td>1001</td><td>1378</td><td>1873</td><td>1.57</td><td>1.40</td><td>2.52</td><td>6.1</td><td>46.7</td></tr><tr><td>1k rows, heavy, 1600x900</td><td>MUI X 9.13.0</td><td>8.3</td><td>9.2</td><td>9.3</td><td>0</td><td>41</td><td>101</td><td>1798</td><td>2186</td><td>0.28</td><td>0.29</td><td>1.99</td><td>9.8</td><td>140.3</td></tr><tr><td>100k rows, heavy, 1600x900</td><td>signal-grid</td><td>8.2</td><td>9.7</td><td>33.2</td><td>1</td><td>33</td><td>100001</td><td>1371</td><td>1736</td><td>2.03</td><td>1.47</td><td>1.53</td><td>35.6</td><td>162.7</td></tr><tr><td>100k rows, heavy, 1600x900</td><td>signal-grid + reactSlot</td><td>8.3</td><td>10.5</td><td>17.3</td><td>0</td><td>33</td><td>100001</td><td>1294</td><td>1873</td><td>1.78</td><td>1.44</td><td>3.06</td><td>38.3</td><td>212.1</td></tr><tr><td>100k rows, heavy, 1600x900</td><td>MUI X 9.13.0</td><td>8.3</td><td>9.3</td><td>9.4</td><td>0</td><td>41</td><td>101</td><td>1798</td><td>2529</td><td>0.30</td><td>0.31</td><td>2.19</td><td>45.8</td><td>241.1</td></tr><tr><td>100k rows, plain, 1600x900</td><td>signal-grid</td><td>8.3</td><td>9.3</td><td>10.1</td><td>0</td><td>33</td><td>100001</td><td>249</td><td>476</td><td>1.18</td><td>0.45</td><td>0.74</td><td>35.5</td><td>178.0</td></tr><tr><td>100k rows, plain, 1600x900</td><td>signal-grid + reactSlot</td><td>8.3</td><td>9.3</td><td>9.4</td><td>0</td><td>33</td><td>100001</td><td>414</td><td>649</td><td>1.28</td><td>0.53</td><td>1.95</td><td>37.8</td><td>200.7</td></tr><tr><td>100k rows, plain, 1600x900</td><td>MUI X 9.13.0</td><td>8.3</td><td>9.3</td><td>9.4</td><td>0</td><td>41</td><td>101</td><td>404</td><td>674</td><td>0.32</td><td>0.13</td><td>2.19</td><td>44.9</td><td>268.3</td></tr><tr><td>100k rows, heavy, 720x480</td><td>signal-grid</td><td>8.3</td><td>9.3</td><td>16.3</td><td>0</td><td>22</td><td>100001</td><td>920</td><td>1160</td><td>1.33</td><td>1.24</td><td>1.33</td><td>35.6</td><td>199.4</td></tr><tr><td>100k rows, heavy, 720x480</td><td>signal-grid + reactSlot</td><td>8.3</td><td>9.3</td><td>16.9</td><td>0</td><td>22</td><td>100001</td><td>792</td><td>1237</td><td>1.33</td><td>1.11</td><td>2.89</td><td>37.7</td><td>182.1</td></tr><tr><td>100k rows, heavy, 720x480</td><td>MUI X 9.13.0</td><td>8.3</td><td>9.3</td><td>9.6</td><td>0</td><td>29</td><td>101</td><td>1294</td><td>1598</td><td>0.34</td><td>0.36</td><td>2.56</td><td>44.8</td><td>348.5</td></tr><tr><td>100k rows, plain, 720x480</td><td>signal-grid</td><td>8.3</td><td>9.2</td><td>9.3</td><td>0</td><td>22</td><td>100001</td><td>172</td><td>332</td><td>0.89</td><td>0.38</td><td>0.76</td><td>35.5</td><td>183.7</td></tr><tr><td>100k rows, plain, 720x480</td><td>signal-grid + reactSlot</td><td>8.3</td><td>9.3</td><td>33.1</td><td>1</td><td>22</td><td>100001</td><td>282</td><td>445</td><td>1.10</td><td>0.45</td><td>2.55</td><td>37.2</td><td>229.9</td></tr><tr><td>100k rows, plain, 720x480</td><td>MUI X 9.13.0</td><td>8.3</td><td>9.3</td><td>9.3</td><td>0</td><td>29</td><td>101</td><td>308</td><td>518</td><td>0.29</td><td>0.12</td><td>2.11</td><td>44.4</td><td>302.3</td></tr><tr><td>100k rows, heavy, 2560x1440</td><td>signal-grid</td><td>8.9</td><td>17.5</td><td>25.9</td><td>0</td><td>48</td><td>100001</td><td>1986</td><td>2456</td><td>3.12</td><td>2.23</td><td>1.81</td><td>35.6</td><td>189.2</td></tr><tr><td>100k rows, heavy, 2560x1440</td><td>signal-grid + reactSlot</td><td>9.2</td><td>24.3</td><td>34.1</td><td>2</td><td>48</td><td>100001</td><td>1898</td><td>2668</td><td>2.88</td><td>2.32</td><td>4.32</td><td>38.7</td><td>225.0</td></tr><tr><td>100k rows, heavy, 2560x1440</td><td>MUI X 9.13.0</td><td>15.8</td><td>17.6</td><td>25.1</td><td>0</td><td>41</td><td>101</td><td>1798</td><td>2186</td><td>0.37</td><td>0.38</td><td>3.15</td><td>45.4</td><td>315.4</td></tr><tr><td>100k rows, plain, 2560x1440</td><td>signal-grid</td><td>8.5</td><td>17.4</td><td>25.7</td><td>0</td><td>48</td><td>100001</td><td>354</td><td>656</td><td>2.02</td><td>0.66</td><td>1.04</td><td>35.5</td><td>183.7</td></tr><tr><td>100k rows, plain, 2560x1440</td><td>signal-grid + reactSlot</td><td>8.3</td><td>16.7</td><td>17.2</td><td>0</td><td>48</td><td>100001</td><td>594</td><td>904</td><td>1.95</td><td>0.76</td><td>2.59</td><td>38.2</td><td>194.7</td></tr><tr><td>100k rows, plain, 2560x1440</td><td>MUI X 9.13.0</td><td>9.3</td><td>24.9</td><td>26.7</td><td>0</td><td>41</td><td>101</td><td>404</td><td>661</td><td>0.38</td><td>0.14</td><td>2.51</td><td>44.9</td><td>269.6</td></tr><tr><td>100k rows, heavy, overscan 32</td><td>signal-grid</td><td>16.7</td><td>33.0</td><td>41.5</td><td>6</td><td>89</td><td>100001</td><td>3667</td><td>4424</td><td>5.04</td><td>3.75</td><td>2.83</td><td>35.6</td><td>220.3</td></tr><tr><td>100k rows, heavy, overscan 32</td><td>signal-grid + reactSlot</td><td>8.4</td><td>16.7</td><td>34.2</td><td>1</td><td>89</td><td>100001</td><td>1226</td><td>4841</td><td>2.41</td><td>1.38</td><td>4.47</td><td>40.7</td><td>209.0</td></tr><tr><td>100k rows, heavy, overscan 32</td><td>MUI X 9.13.0</td><td>8.3</td><td>17.2</td><td>20.2</td><td>0</td><td>41</td><td>101</td><td>1798</td><td>2186</td><td>0.34</td><td>0.38</td><td>2.86</td><td>45.2</td><td>313.0</td></tr></tbody></table><p><code>nodes</code> is counted on the last measured frame. <code>settled nodes</code> is the CDP node count taken after the burst, so the gap between the two is content that committed outside the scroll frame. Machine: Apple M2 Pro, 12 cores, 16 GiB, node v24.15.0, run 2026-09-12. Raw: <code>bench/versus.json</code>, chart: <code>bench/versus.svg</code>.</p><h2 id="_4-where-mui-x-wins" tabindex="-1">4. Where MUI X wins <a class="header-anchor" href="#_4-where-mui-x-wins" aria-label="Permalink to “4. Where MUI X wins”">​</a></h2><p>Two columns, on every case in the matrix, and one of them is the largest term in the frame.</p><table tabindex="0"><thead><tr><th>column</th><th>signal-grid</th><th>MUI X</th><th>MUI X is faster by</th></tr></thead><tbody><tr><td>layout ms per frame, 101 rows</td><td>0.98</td><td>0.28</td><td>3.5x</td></tr><tr><td>style recalc ms per frame, 101 rows</td><td>1.23</td><td>0.30</td><td>4.1x</td></tr><tr><td>layout ms per frame, 100k heavy</td><td>2.03</td><td>0.30</td><td>6.8x</td></tr><tr><td>style recalc ms per frame, 100k heavy</td><td>1.47</td><td>0.31</td><td>4.7x</td></tr><tr><td>layout ms per frame, overscan 32</td><td>5.04</td><td>0.34</td><td>14.8x</td></tr><tr><td>style recalc ms per frame, overscan 32</td><td>3.75</td><td>0.38</td><td>9.9x</td></tr><tr><td>layout + style + script, 101 rows</td><td>3.15</td><td>2.57</td><td>1.23x</td></tr></tbody></table><p>Read the last row carefully, because it is the one that decides the claim. At the only scroll depth both engines support, MUI X spends less total measured work per frame than signal-grid does. The package wins the script column and loses the two browser columns, and the browser columns are bigger.</p><p>The gap widens with the buffer. At overscan 32 signal-grid holds 89 rows against MUI X&#39;s 41 and spends 8.79 ms per frame in layout and style against 0.72, which is 6 measured frames over 32 ms against none. Buffer size was already the one factor that broke the frame in the single-engine matrix (<code>bench/README.md</code>); this says the browser cost of the rows a buffer adds is where the package is furthest from the ceiling it is aiming at.</p><p>What the difference is made of is not established by these numbers. Both engines move their rendered run with a <code>transform</code>, so translation is not it, and the <code>101 rows</code> case shows relation size accounts for about half of signal-grid&#39;s layout time and none of the remainder. Attributing the rest needs a trace, which is listed under <a href="#_8-what-this-does-not-measure">what this does not measure</a>.</p><h2 id="_5-where-signal-grid-wins" tabindex="-1">5. Where signal-grid wins <a class="header-anchor" href="#_5-where-signal-grid-wins" aria-label="Permalink to “5. Where signal-grid wins”">​</a></h2><table tabindex="0"><thead><tr><th>column</th><th>signal-grid</th><th>MUI X</th><th>signal-grid is faster by</th></tr></thead><tbody><tr><td>rows the scroller will travel</td><td>100,001</td><td>101</td><td>990x</td></tr><tr><td>script ms per frame, 100k heavy</td><td>1.53</td><td>2.19</td><td>1.43x</td></tr><tr><td>script ms per frame, 100k plain</td><td>0.74</td><td>2.19</td><td>2.95x</td></tr><tr><td>frame p50, 2560x1440 heavy</td><td>8.9</td><td>15.8</td><td>1.78x</td></tr><tr><td>time to first row, 100k heavy</td><td>162.7 ms</td><td>241.1 ms</td><td>1.48x</td></tr><tr><td>time to first row, 1k heavy</td><td>38.1 ms</td><td>140.3 ms</td><td>3.68x</td></tr><tr><td>retained heap, 1k rows</td><td>3.8 MB</td><td>9.8 MB</td><td>2.58x</td></tr><tr><td>retained heap, 100k rows</td><td>35.6 MB</td><td>45.8 MB</td><td>1.29x</td></tr></tbody></table><p>The 2560x1440 row is the one a user would feel: MUI X lands on the second vsync tick and holds 15.8 ms at p50 while signal-grid holds 8.9, even though MUI X&#39;s own layout, style and script counters add to 3.90 against signal-grid&#39;s 7.16. A frame is longer than the counters that name it, and <code>ScriptDuration</code> does not carry React work scheduled outside the animation frame.</p><p>The heap column is the flat part. MUI X holds about 6 MB more than signal-grid before a row is scrolled, and that difference is nearly constant from 1,000 rows to 100,000, so it is fixed grid state rather than per-row overhead.</p><h2 id="_6-row-count-ceiling" tabindex="-1">6. Row-count ceiling <a class="header-anchor" href="#_6-row-count-ceiling" aria-label="Permalink to “6. Row-count ceiling”">​</a></h2><p>Both engines reach a million rows in the <code>rows</code> prop on this machine. Only one of them will scroll through them.</p><table tabindex="0"><thead><tr><th>engine</th><th>rows</th><th>first row reached</th><th>mount ms</th><th>heap MB</th></tr></thead><tbody><tr><td>signal-grid</td><td>100,000</td><td>yes</td><td>287</td><td>35.1</td></tr><tr><td>signal-grid</td><td>250,000</td><td>yes</td><td>563</td><td>81.5</td></tr><tr><td>signal-grid</td><td>500,000</td><td>yes</td><td>1320</td><td>160.8</td></tr><tr><td>signal-grid</td><td>1,000,000</td><td>yes</td><td>2599</td><td>320.4</td></tr><tr><td>MUI X 9.13.0</td><td>100,000</td><td>yes</td><td>316</td><td>43.5</td></tr><tr><td>MUI X 9.13.0</td><td>250,000</td><td>yes</td><td>519</td><td>94.1</td></tr><tr><td>MUI X 9.13.0</td><td>500,000</td><td>yes</td><td>870</td><td>181.0</td></tr><tr><td>MUI X 9.13.0</td><td>1,000,000</td><td>yes</td><td>2002</td><td>355.5</td></tr></tbody></table><p>Those rows are a real array on both sides, which is the equalisation this page needed. signal-grid also accepts a lazy relation: <code>bench/scroll/0_bench.ts</code> hands it a <code>Proxy</code> over an empty array that mints a row on index access, and the single-engine matrix runs a million rows that way with nothing materialised. MUI X copies <code>rows</code> into its own id lookup on mount, so the same <code>Proxy</code> buys it nothing.</p><h2 id="_7-what-a-reactslot-cell-costs" tabindex="-1">7. What a <code>reactSlot</code> cell costs <a class="header-anchor" href="#_7-what-a-reactslot-cell-costs" aria-label="Permalink to “7. What a reactSlot cell costs”">​</a></h2><p><code>@hafley66/signal-grid/react</code> is deliberately small. <code>GridView</code> mounts the box with <code>useEffect(() =&gt; render(grid, el).stop, [grid])</code> and nothing else; the grid owns every node inside it, and cell content never passes through React reconciliation. A consumer opts back in per slot with <code>reactSlot</code>, which hands the returned JSX a root and gives back the <code>{ content, unsubscribe }</code> shape the slot contract already carries.</p><p>The <code>signal-grid + reactSlot</code> rows of the matrix are that opt-in applied to every cell, which is the worst case a consumer can build.</p><table tabindex="0"><thead><tr><th>what it costs</th><th>plain DOM slot</th><th>every cell a <code>reactSlot</code></th><th>change</th></tr></thead><tbody><tr><td>script ms per frame, 100k heavy</td><td>0.89</td><td>1.24</td><td>1.39x</td></tr><tr><td>script ms per frame, 100k plain</td><td>0.47</td><td>0.59</td><td>1.26x</td></tr><tr><td>script ms per frame, 101 rows heavy</td><td>0.73</td><td>0.98</td><td>1.34x</td></tr><tr><td>layout ms per frame, 100k heavy</td><td>1.16</td><td>1.17</td><td>1.01x</td></tr><tr><td>retained heap, 1k rows</td><td>3.8 MB</td><td>6.8 MB</td><td>+3.0 MB</td></tr><tr><td>retained heap, 100k rows</td><td>35.6 MB</td><td>38.7 MB</td><td>+3.1 MB</td></tr><tr><td>retained heap, overscan 32</td><td>35.6 MB</td><td>41.4 MB</td><td>+5.8 MB</td></tr><tr><td>DOM elements</td><td>one per cell content</td><td>one extra <code>div.sg-react</code> wrapper per cell</td><td>+1 per cell</td></tr></tbody></table><p>About a third more script time per frame, three megabytes of retained roots, and one extra element per cell. Layout and style do not move, because the nodes React commits are the nodes the DOM slot would have written. On the script column the opt-in still costs less than MUI X does: 1.24 ms against 1.71 at 100k heavy.</p><h3 id="the-two-things-that-got-it-there" tabindex="-1">The two things that got it there <a class="header-anchor" href="#the-two-things-that-got-it-there" aria-label="Permalink to “The two things that got it there”">​</a></h3><p>The first measurement of this page read 3.06 ms per frame at 100k heavy, and the number was a lie in both directions. <code>createRoot</code> gives a concurrent root, which commits the cell body off the animation frame; at overscan 32 the react page counted 1,226 elements on the last measured frame against 4,841 once the burst had finished. The scroll frame carried the row scaffolding and the cells arrived late, so the harness timed a grid that was rendering nothing.</p><p><code>bench/scroll/chaos.html</code> is that effect&#39;s limit case, and it is where the two fixes came from. Sixteen drivers moving at once never leave React an idle frame:</p><table tabindex="0"><thead><tr><th><code>reactSlot</code></th><th>fps</th><th>package ms/f</th><th>cells filled</th><th>heap</th></tr></thead><tbody><tr><td><code>createRoot</code> + <code>render</code></td><td>30</td><td>4.91</td><td>0 of 416</td><td>309 MB</td></tr><tr><td>plus <code>flushSync</code></td><td>21</td><td>2.79</td><td>224 of 224</td><td>174 MB</td></tr><tr><td>plus a root pool</td><td>23</td><td>2.52</td><td>192 of 192</td><td>154 MB</td></tr><tr><td>the DOM slot, for scale</td><td>25</td><td>2.75</td><td>120 of 120</td><td>106 MB</td></tr></tbody></table><p><code>sync: true</code> wraps the render in <code>flushSync</code>, so the cell commits inside the frame that asked for it. <code>flushSync</code> is a no-op while React is already rendering, which is where the initial mount runs, so the first commit still lands on React&#39;s own schedule and no warning is emitted.</p><p><code>pool: 256</code> keeps the <code>{ host, root }</code> pair when a cell leaves and hands it to the next cell instead of building a root and tearing it down. A scroll retires every rendered cell each frame, so without a pool the page builds and destroys a root per cell per frame.</p><p>Both default on. <code>reactSlot(view, { sync: false, pool: 0 })</code> is the old behaviour if a consumer wants React&#39;s own scheduling back.</p><p>Use <code>GridView</code> for the box. Reach for <code>reactSlot</code> on the cells that need a React component in them, and expect about a third more per-frame script time on those cells.</p><h2 id="_8-what-this-does-not-measure" tabindex="-1">8. What this does not measure <a class="header-anchor" href="#_8-what-this-does-not-measure" aria-label="Permalink to “8. What this does not measure”">​</a></h2><ul><li>Why the layout and style columns differ by four to seven times. The counters say they do; a trace would say what of.</li><li><code>DataGridPro</code> and <code>DataGridPremium</code>. The MIT package is what is installed here, and the page cap in section 2 is a property of that tier, not of the codebase behind it.</li><li>Sorting, filtering, grouping or editing under load. This is a scroll.</li><li>Firefox and safari. Chromium only, same as the single-engine matrix.</li><li>Paint and compositing. <code>LayoutDuration</code>, <code>RecalcStyleDuration</code> and <code>ScriptDuration</code> do not add up to a frame, and the <code>2560x1440</code> case is where that gap is widest.</li><li>A MUI X scroll deeper than 100 rows, which the MIT tier will not perform.</li></ul><h2 id="_9-reproducing-it" tabindex="-1">9. Reproducing it <a class="header-anchor" href="#_9-reproducing-it" aria-label="Permalink to “9. Reproducing it”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd packages/signal-grid</span></span>
<span class="line"><span>node ../../scripts/browser-queue.mjs node bench/versus.mjs</span></span></code></pre></div><p>Writes <code>bench/versus.json</code> and <code>bench/versus.svg</code> and prints the matrix above. <code>node bench/versus.mjs --no-build</code> reuses <code>bench/scroll/dist</code>, and <code>--no-ceiling</code> skips section 6. The three pages can also be opened by hand with <code>pnpm bench:knobs</code> running: <code>bench/scroll/index.html</code>, <code>bench/scroll/react.html</code> and <code>bench/scroll/mui.html</code> all take the same query string.</p>`,45)])}var p=c(d,[[`render`,f]]);export{u as __pageData,p as default};